import sqlite3,re,sys
sys.path.insert(0,'/tmp/claude-0/-home-user-guidebook/982e23dc-1318-5999-92af-f35647743666/scratchpad')
from stagemap import STAGE
con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
views={n:s for n,s in con.execute("select name,sql from sqlite_master where type='view'")}
def reads(sql, seen=None):
    seen = seen or set()
    out=set()
    for m in re.findall(r'(?:FROM|JOIN)\s+"?([a-z_][a-z0-9_]*)"?', sql, re.I):
        if m in views and m not in seen:
            out |= reads(views[m], seen|{m})
        elif m in STAGE:
            out.add(m)
    return out
rows=[]
for n in sorted(views):
    t=reads(views[n]); st=sorted({STAGE[x] for x in t})
    rows.append((n,st,sorted(t)))
print("=== CROSS-STAGE views (the pointer, expressed in SQL) ===")
for n,st,t in rows:
    if len(st)>1: print(f"  {n:26} {' + '.join(st):26} {t}")
print("\n=== single-stage views ===")
for n,st,t in rows:
    if len(st)<=1: print(f"  {n:26} {(st[0] if st else '(none)'):26} {t}")
