      <tr><td><span class="m">items.item_code</span></td><td><span class="chip st-substrate">substrate</span></td><td class="num">10</td><td><div class="bar"><i style="width:90px"></i><span>res 1 · evi 1 · jud 4 · syn 1 · ren 3</span></div></td></tr>
