      <tr><td><span class="m">evidence_sources.ref_id</span></td><td><span class="chip st-evidence">evidence</span></td><td class="num">6</td><td><div class="bar"><i style="width:54px"></i><span>res 1 · jud 2 · syn 1 · ren 1 · sub 1</span></div></td></tr>
      <tr><td><span class="m">gaps.gap_id</span></td><td><span class="chip st-research">research</span></td><td class="num">2</td><td><div class="bar"><i style="width:18px"></i><span>evi 1 · jud 1</span></div></td></tr>
