      <tr><td><span class="m">reasoning_doc_citations.citation_id</span></td><td><span class="chip st-synthesis">synthesis</span></td><td class="num">1</td><td><div class="bar"><i style="width:9px"></i><span>evi 1</span></div></td></tr>
    </tbody>
