    for tok in set(re.findall(r'\b\w+\b', sql)):
        if tok==name: continue
        if tok in tables: out.add(tok)
        elif tok in views and tok not in seen:
            seen.add(tok); out |= refs(tok, seen)
    return out
for v in sorted(views):
    print(v, "->", sorted(refs(v)))
